const KEY='sb_publishable_Fh0fWwz6kCfMlcgYCsTJOA_eZmHsib4';
const API=BASE+'/functions/v1/v1-runtime';
const params=new URLSearchParams(location.search);
let hospitalEntryPending=params.get('portal')==='hospital';
let hospitalEntryDenied=false;
let vetEntryPending=params.get('portal')==='vet';
let vetEntryDenied=false;
